func encodeTextBlockToWhoResultTextBlockTransport(v *chorus.TextBlock) *WhoResultTextBlockTransport {
	res := &WhoResultTextBlockTransport{}
	var contentValue WhoResultcontentTransport
	switch string(v.Content.Kind()) {
	case "text":
		actual, _ := v.Content.AsText()
		var obj *WhoResultcontentTextTransport
		if actual != nil {
			obj = encodeContentTextToWhoResultcontentTextTransport(actual)
		}
		u := contentValue
		u.SetText((*WhoResultcontentTextTransport)(obj))
		contentValue = u
	}
	res.Content = &contentValue

	return res
}
